insert into tax_rate (jurisdiction_code, tax_type_code, valid_from, headline_rate, rate_min, rate_max, threshold_amount, threshold_note, note, source_url, verified_on, next_check_on, needs_verification) values ('ES-SS', 'WEALTH_SOLIDARITY', '2026-01-01', 3.5, 1.7, 3.5, 3900000, '0% on the first €3.2m of taxable base, which is net wealth after the €700,000 exemption, so the tax starts at €3.9m of net wealth.', 'Gipuzkoa solidarity tax on large fortunes, tax year 2026 (in force while the state tax is): 1.7% to €6.4m of taxable base, 2.1% to €12.8m, 2.5% to €14.5m, 3.5% above, nothing on the first €3.2m, after an exemption of €700,000; the wealth tax paid is deducted (REAF, "Panorama de la Fiscalidad Autonómica y Foral 2026"). NOT ONE RATE: headline = the top band.', 'https://economistas.es/Contenido/REAF/Informes/Panorama2026.pdf', '2026-10-03', '2027-01-15', false) on conflict (jurisdiction_code, tax_type_code) where valid_to is null do update set headline_rate = excluded.headline_rate, rate_min = excluded.rate_min, rate_max = excluded.rate_max, threshold_amount = excluded.threshold_amount, threshold_note = excluded.threshold_note, note = excluded.note, source_url = excluded.source_url, verified_on = excluded.verified_on, next_check_on = excluded.next_check_on, needs_verification = excluded.needs_verification;
