insert into tax_rate (jurisdiction_code, tax_type_code, valid_from, headline_rate, rate_min, rate_max, threshold_amount, threshold_note, note, source_url, verified_on, next_check_on, needs_verification) values ('ES-VI', 'WEALTH_NET', '2026-01-01', 2.5, 0.2, 2.5, 800000, 'Tax-free amount (mínimo exento) €800,000.', 'Álava (foral wealth tax), tax year 2026: tax-free amount €800,000, scale 0.2% to 2.5% (REAF, "Panorama de la Fiscalidad Autonómica y Foral 2026"). NOT ONE RATE: headline = the top band.', 'https://economistas.es/Contenido/REAF/Informes/Panorama2026.pdf', '2026-10-03', '2027-01-15', false) on conflict (jurisdiction_code, tax_type_code) where valid_to is null do update set headline_rate = excluded.headline_rate, rate_min = excluded.rate_min, rate_max = excluded.rate_max, threshold_amount = excluded.threshold_amount, threshold_note = excluded.threshold_note, note = excluded.note, source_url = excluded.source_url, verified_on = excluded.verified_on, next_check_on = excluded.next_check_on, needs_verification = excluded.needs_verification;
